// Filter sessions to the target event AND only those actually on sale.
// Also derive a 'smart' event name that handles Onebox placeholder titles.
const eventId = Number($('Vars').first().json.event_id);
const resp = $input.first().json;
const sessions = resp.data ?? [];

function isPlaceholder(s) {
  if (!s) return true;
  const x = s.trim();
  return (x.startsWith('*')
          || /\bAPI\b/i.test(x)
          || ['NUMERADO','EVENT','TEST','DEMO'].includes(x.toUpperCase()));
}

function smartTitle(s) {
  const candidates = [s.event && s.event.name, s.name];
  const real = candidates.find(c => c && !isPlaceholder(c));
  if (real) return real;
  const venue = s.venue && s.venue.name;
  const dateStr = s.date && s.date.start
    ? new Date(s.date.start).toLocaleDateString('es-ES', { day: 'numeric', month: 'short', year: 'numeric' })
    : '';
  if (venue && dateStr) return 'Partido en ' + venue + ' — ' + dateStr;
  if (venue) return 'Partido en ' + venue;
  return 'Próximo partido';
}

return sessions
  .filter(s => Number(s.event && s.event.id) === eventId)
  .filter(s => s.on_sale === true && s.sold_out !== true)
  .map(s => ({
    json: {
      session_id:   s.id,
      session_name: s.name,
      event_id:     s.event && s.event.id,
      event_name:   smartTitle(s),
      venue:        (s.venue && s.venue.name) || null,
      date:         (s.date && s.date.start) || null,
      on_sale:      !!s.on_sale,
      sold_out:     !!s.sold_out
    }
  }));

// Emit one item per (session, sector) that has available seats.
const sessions = $('Filter by event_id').all();
const responses = $input.all();

const out = [];
for (let i = 0; i < responses.length; i++) {
  const avail = responses[i].json;
  const sess  = sessions[i] && sessions[i].json || {};
  const sessionId = avail.id || sess.session_id;

  for (const sec of avail.sectors || []) {
    let available = 0, total = 0;
    for (const pt of sec.price_types || []) {
      available += (pt.availability && pt.availability.available) || 0;
      total     += (pt.availability && pt.availability.total) || 0;
    }
    if (available > 0) {
      out.push({ json: {
        event_id:   sess.event_id,
        session_id: sessionId,
        event_name: sess.event_name,
        venue:      sess.venue,
        date:       sess.date,
        grada_id:   sec.id,
        grada_name: sec.name,
        grada_code: sec.code || null,
        available,
        total
      }});
    }
  }
}
return out;

// For each grada with availability, find subscribers tagged with
// event:<id>, grada:<id>, source:avisame, AND NOT yet tagged
// notified:<event>:<grada>. Returns one item per (subscriber, grada).
const members = ($('Aggregate members').first().json.members) || [];
const gradas  = $input.all();
const purchaseTpl = ($('Vars').first().json.purchase_url_template) || '';
const wantSource = 'source:avisame';

const out = [];
for (const g of gradas) {
  const ctx = g.json;
  const wantEvent    = 'event:' + ctx.event_id;
  const wantGrada    = 'grada:' + ctx.grada_id;
  const notifiedTag  = 'notified:' + ctx.event_id + ':' + ctx.grada_id;

  for (const m of members) {
    if (m.status !== 'subscribed') continue;
    const tagNames = ((m.tags) || []).map(t => t.name);
    if (!tagNames.includes(wantEvent))    continue;
    if (!tagNames.includes(wantGrada))    continue;
    if (!tagNames.includes(wantSource))   continue;
    if (tagNames.includes(notifiedTag))   continue;  // dedup: already alerted

    out.push({ json: {
      email:           m.email_address,
      subscriber_hash: m.id,
      first_name:      (m.merge_fields && m.merge_fields.FNAME) || '',
      last_name:       (m.merge_fields && m.merge_fields.LNAME) || '',
      event_id:        ctx.event_id,
      event_name:      ctx.event_name,
      session_id:      ctx.session_id,
      grada_id:        ctx.grada_id,
      grada_name:      ctx.grada_name,
      available:       ctx.available,
      notified_tag:    notifiedTag,
      purchase_url: purchaseTpl
        .replace('{sessionId}', String(ctx.session_id))
        .replace('{eventId}',   String(ctx.event_id))
        .replace('{gradaId}',   String(ctx.grada_id))
    }});
  }
}
return out;
